17	        "'use client';\n\nexport const Foo = () => null;",
18	        '"use client";\n\nexport const Foo = () => null;',
19	        "'use client';\n",
20	    ],
21	    invalid: [
22	        {
23	            code: 'export const Foo = () => null;',
24	            output: "'use client';\n\nexport const Foo = () => null;",
25	            errors: [{ messageId: 'missing' }],
26	        },
